packed for\n        INT4 (pack_factor=8) or INT8 (pack_factor=4) quantization.\n    - C: The output cache tensor with shape (M, topk, N), where M is the\n        total number of tokens post padding, topk is the number of times\n        each token is repeated, and N is the output feature dimension.\n    - sorted_token_ids: A tensor containing the sorted indices of tokens,\n        repeated topk times and arranged by the expert index they are\n        assigned to.\n    - expert_ids: A tensor containing the indices of the expert for each\n        block. It determines which expert matrix from B should be used for\n        each block in A.\n    - b_scale_ptr: Pointer to the per-group scale tensor with shape\n        (E, K // group_size, N).\n    - b_zp_ptr: Pointer to the per-group zero point tensor with shape\n        (E, K // group_size, N // pack_factor) for AWQ/GPTQ.\n    \n    This kernel performs the multiplication of a token by its corresponding\n    expert matrix as determined by `expert_ids`. The sorting of\n    `sorted_token_ids` by expert index and padding ensures divisibility by\n    BLOCK_SIZE_M, which is necessary to maintain consistency in block matrix\n    multiplication across different blocks processed by the same expert.\n    \"\"\"\n    # -----------------------------------------------------------\n    # Map program ids `pid` to the block of C it should compute.\n    # This is done in a grouped ordering to promote L2 data reuse.\n    pid = tl.program_id(axis=0)\n    num_pid_m = tl.cdiv(EM, BLOCK_SIZE_M)\n    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)\n    num_pid_in_group = GROUP_SIZE_M * num_pid_n\n    group_id = pid // num_pid_in_group\n    first_pid_m = group_id * GROUP_SIZE_M\n    group_size_m = min(num_pid_m - first_pid_m, GROUP_SIZE_M)\n    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)\n    pid_n = (pid % num_pid_in_group) // group_size_m\n\n    # ----------------------------------------------------------\n    # Create pointers for the first blocks of A and B.\n    # We will advance this pointer as we move in the K direction\n    # and accumulate\n    # `a_ptrs` is a block of [BLOCK_SIZE_M, BLOCK_SIZE_K] pointers\n    # `b_ptrs` is a block of [BLOCK_SIZE_K, BLOCK_SIZE_N] pointers\n    num_tokens_post_padded = tl.load(num_tokens_post_padded_ptr)\n    if pid_m * BLOCK_SIZE_M >= num_tokens_post_padded:\n        return\n    offs_token_id = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M).to(\n        tl.int64)\n    offs_token = tl.load(sorted_token_ids_ptr + offs_token_id)\n    token_mask = offs_token < num_valid_tokens\n\n    offs_bn = (pid_n * BLOCK_SIZE_N +\n               tl.arange(0, BLOCK_SIZE_N).to(tl.int64)) % N\n    offs_k = tl.arange(0, BLOCK_SIZE_K)\n    a_ptrs = a_ptr + (offs_token[:, None] // top_k * stride_am +\n                      offs_k[None, :] * stride_ak)\n\n    off_experts = tl.load(expert_ids_ptr + pid_m).to(tl.int64)\n    \n    # For GPTQ/AWQ, weights are packed\n    # b_ptrs points to packed weights: (E, N, K // pack_factor)\n    # pack_factor = 8 for INT4, 4 for INT8\n    if use_int4_w4a16:\n        pack_factor = 8\n    else:  # use_int8_w8a16\n        pack_factor = 4\n    \n    # B is stored as (E, N, K // pack_factor)\n    # stride_be: stride for expert dimension\n    # stride_bn: stride for N dimension (output)\n    # stride_bk: stride for K dimension (input, packed)\n    b_ptrs = b_ptr + off_experts * stride_be + (offs_bn[None, :] * stride_bn +\n                                                (offs_k[:, None] // pack_factor) * stride_bk)\n    \n    # Load scales and zero points for this block\n    # scales shape: (E, K // group_size, N)\n    # zp shape: (E, K // group_size, N // pack_factor)\n    offs_bsk = offs_k // group_size\n    b_scale_ptrs = b_scale_ptr + off_experts * stride_bse + offs_bsk[\n        :, None] * stride_bsk + offs_bn[None, :] * stride_bsn\n    b_scale = tl.load(b_scale_ptrs, mask=offs_k[:, None] < K, other=0.0)\n    \n    if has_zp:\n        b_zp_ptrs = b_zp_ptr + off_experts * stride_bze + offs_bsk[\n            :, None] * stride_bzk + (offs_bn[None, :] // pack_factor) * stride_bzn\n        b_zp = tl.load(b_zp_ptrs, mask=offs_k[:, None] < K, other=0.0)\n    else:\n        b_zp = tl.zeros((BLOCK_SIZE_K, BLOCK_SIZE_N), dtype=tl.int32)\n\n    # Create reverse AWQ order as tensor: [0, 4, 1, 5, 2, 6, 3, 7]\n    # that will map given indices to the correct order.\n    reverse_awq_order_tensor = ((tl.arange(0, 2) * 4)[None, :] +\n                                tl.arange(0, 4)[:, None]).reshape(8)\n\n    # Create the necessary shifts to use to unpack.\n    if use_int4_w4a16:\n        shifts = reverse_awq_order_tensor * 4\n        shifts = tl.broadcast_to(shifts[None, :],\n                                 (BLOCK_SIZE_K * (BLOCK_SIZE_N // 8), 8))\n        shifts = tl.reshape(shifts, (BLOCK_SIZE_K, BLOCK_SIZE_N))\n    else:  # use_int8_w8a16\n        shifts = tl.arange(0, 4) * 8\n        shifts = tl.broadcast_to(shifts[None, :],\n                                 (BLOCK_SIZE_K * (BLOCK_SIZE_N // 4), 4))\n        shifts = tl.reshape(shifts, (BLOCK_SIZE_K, BLOCK_SIZE_N))\n\n    # -----------------------------------------------------------\n    # Iterate to compute a block of the C matrix.\n    # We accumulate into a `[BLOCK_SIZE_M, BLOCK_SIZE_N]` block\n    # of fp32 values for higher accuracy.\n    # `accumulator` will be converted back to fp16 after the loop.\n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)\n\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):\n        # Load the next block of A and B, generate a mask by checking the\n        # K dimension.\n        a = tl.load(a_ptrs,\n                    mask=token_mask[:, None] &\n                    (offs_k[None, :] < K - k * BLOCK_SIZE_K),\n                    other=0.0)\n        \n        # Load packed weights\n        # For INT4: b_ptrs points to (K // 8, N // 8) packed weights\n        # For INT8: b_ptrs points to (K // 4, N // 4) packed weights\n        if use_int4_w4a16:\n            b_packed_ptrs = b_ptr + off_experts * stride_be + (\n                offs_bn[None, :] // 8 * stride_bn +\n                (offs_k[:, None] // 8) * stride_bk)\n            b_packed = tl.load(b_packed_ptrs,\n                              mask=offs_k[:, None] < K,\n                              other=0)\n            # Unpack: interleave 3 times to expand from (K, N//8) to (K, N)\n            b = b_packed\n            b = tl.interleave(b, b)\n            b = tl.interleave(b, b)\n            b = tl.interleave(b, b)\n            # Apply shifts and mask to get 4-bit values\n            b = (b >> shifts) & 0xF\n        else:  # use_int8_w8a16\n            b_packed_ptrs = b_ptr + off_experts * stride_be + (\n                offs_bn[None, :] // 4 * stride_bn +\n                (offs_k[:, None] // 4) * stride_bk)\n            b_packed = tl.load(b_packed_ptrs,\n                              mask=offs_k[:, None] < K,\n                              other=0)\n            # Unpack: interleave 2 times to expand from (K, N//4) to (K, N)\n            b = b_packed\n            b = tl.interleave(b, b)\n            b = tl.interleave(b, b)\n            # Apply shifts and mask to get 8-bit values\n            b = (b >> shifts) & 0xFF\n        \n        # Dequantize: (weight - zero_point) * scale\n        b_fp32 = (b.to(tl.float32) - b_zp.to(tl.float32)) * b_scale.to(tl.float32)\n        \n        # We accumulate along the K dimension.\n        accumulator += tl.dot(a.to(compute_type), b_fp32.to(compute_type))\n        \n        # Advance the ptrs to the next K block.\n        a_ptrs += BLOCK_SIZE_K * stride_ak\n        if use_int4_w4a16:\n            b_ptrs += BLOCK_SIZE_K * stride_bk // 8\n        else:\n            b_ptrs += BLOCK_SIZE_K * stride_bk // 4\n\n    if MUL_ROUTED_WEIGHT:\n        moe_weight = tl.load(topk_weights_ptr + offs_token,\n                             mask=token_mask,\n                             other=0)\n        accumulator = accumulator * moe_weight[:, None]\n    \n    accumulator = accumulator.to(compute_type)\n    \n    # -----------------------------------------------------------\n    # Write back the block of the output\n    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    c_ptrs = c_ptr + stride_cm * offs_token[:, None] + stride_cn * offs_cn[\n        None, :]\n    c_mask = token_mask[:, None] & (offs_cn[None, :] < N)\n    tl.store(c_ptrs, accumulator, mask=c_mask)"
